// Espera o payload do front (o mesmo da esteira, inalterado):
// { email, empresa_select, filename, file_base64, mime_type, tipo_faturamento }
const body = $json.body ?? $json;
if (!body.file_base64) {
  throw new Error('file_base64 ausente no payload recebido.');
}
const filename = body.filename || 'arquivo.xlsx';
const extensao = (filename.includes('.') ? filename.split('.').pop() : '').toLowerCase();

return [{
  json: {
    filename,
    extensao,
    empresa: body.empresa_select ?? '',
    tipo_faturamento: body.tipo_faturamento ?? 'VALE',
  },
  binary: {
    data: {
      data: body.file_base64,
      mimeType: body.mime_type || 'application/octet-stream',
      fileName: filename,
    },
  },
}];

// ================= CONFIG (ajuste para a sua tabela real) =================
const TABELA = 'rfs_faturados';
const COL_RF = 'rf';               // coluna unica da tabela (PRIMARY KEY)
// ==========================================================================
// O rf e PRIMARY KEY, entao o INSERT IGNORE nunca duplica registros.

// Mesma normalizacao do front (conferencia_rf.normalizar_rf)
const normalizar = (v) => {
  if (v === null || v === undefined) return '';
  let t = String(v).trim();
  if (/^\d+\.0$/.test(t)) t = t.slice(0, -2);
  return t;
};

const rfs = new Set();
for (const item of $input.all()) {
  const j = item.json ?? {};
  const chave = Object.keys(j).find((k) => String(k).trim().toUpperCase() === 'RF');
  if (!chave) continue;
  const rf = normalizar(j[chave]);
  if (rf) rfs.add(rf);
}

if (!rfs.size) {
  throw new Error('Nenhum RF encontrado no arquivo (coluna "RF" ausente ou vazia).');
}

const esc = (s) => String(s).replace(/\\/g, '\\\\').replace(/'/g, "''");
const values = [...rfs].map((rf) => `('${esc(rf)}')`).join(',');

const sql = `INSERT IGNORE INTO ${TABELA} (${COL_RF}) VALUES ${values}`;

return [{ json: { sql, total_rfs: rfs.size } }];
